func cartButtonEnabled(data DetailData) bool {
	if services.ProductSellable(data.Product) {
		return true
	}
	for _, v := range data.Variants {
		if v.Sellable {
			return true
		}
	}
	return false
}

func stockClass(p *models.Product) string {
	if p.Stock > 0 {
		return ""
	}
	return "out"
}

func viewVariants(entries []VariantEntry) []*models.ProductVariant {
	out := make([]*models.ProductVariant, 0, len(entries))
	for _, e := range entries {
		out = append(out, e.Variant)
	}
	return out
}

